//! Scenario (1): the flat v1 listing — every action tells its recipient, the
//! type filters and the id cursors.

use serde_json::json;

use super::support::{
    THUMB, assert_descending, entity_id, flat, ids_of, mix, row_of, sorted, telling, told,
};
use crate::common;

/// Every type the model produces is generated by its real action and
/// shows up for the recipient in `GET /api/v1/notifications`: seven rows
/// on a mixed page naming the right actor and status — `follow`, `mention`,
/// `favourite`, `reblog` and `pleroma:emoji_reaction` with its emoji and
/// stored group key — alice's self-actions told to nobody, and eve's
/// locked inbox holding exactly the `follow_request`.
#[tokio::test]
async fn every_action_tells_the_recipient_in_the_flat_listing() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let seed = mix(&app, &pool).await;

    let rows = flat(&app, &seed.alice, "").await;
    assert_eq!(
        sorted(told(&rows)),
        seed.want,
        "six actions of five types told alice, each exactly once"
    );
    assert_descending(&ids_of(&rows));

    let reaction = row_of(&rows, "pleroma:emoji_reaction");
    assert_eq!(
        reaction["emoji"],
        json!(THUMB),
        "the telling carries the emoji"
    );
    assert_eq!(
        reaction["group_key"],
        json!(format!("pleroma:emoji_reaction-{}-{THUMB}", seed.subject)),
        "and the key its group will read under"
    );
    assert_eq!(
        reaction["pleroma"]["is_seen"],
        json!(false),
        "a fresh telling is unseen"
    );
    let follow_row = row_of(&rows, "follow");
    assert_eq!(
        follow_row["group_key"],
        json!(format!("ungrouped-{}", entity_id(follow_row))),
        "an ungrouped row carries its unique key"
    );
    assert!(
        follow_row.get("status").is_none(),
        "and names no status: {follow_row}"
    );

    assert_eq!(
        told(&flat(&app, &seed.eve, "").await),
        vec![telling("follow_request", &seed.bob, None)],
        "eve is told the pending request — and nothing else"
    );
}

/// On the mixed page, `types[]` keeps only the named types and
/// `exclude_types[]` removes the named ones — each probe over the same
/// seven-row page [`mix`] seeded.
#[tokio::test]
async fn the_flat_page_honors_its_type_filters() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let seed = mix(&app, &pool).await;
    let owed = |kind: &str, actor: &str| telling(kind, actor, Some(&seed.subject));

    assert_eq!(
        flat(&app, &seed.alice, "").await.len(),
        7,
        "seven tellings on the page"
    );
    let kept = sorted(told(
        &flat(
            &app,
            &seed.alice,
            "?types[]=favourite&types[]=pleroma:emoji_reaction",
        )
        .await,
    ));
    assert_eq!(
        kept,
        sorted(vec![
            owed("favourite", &seed.bob),
            owed("favourite", &seed.dave),
            owed("pleroma:emoji_reaction", &seed.bob),
        ]),
        "types[] keeps exactly the named rows"
    );
    let mentions = sorted(told(&flat(&app, &seed.alice, "?types[]=mention").await));
    assert_eq!(
        mentions,
        sorted(vec![
            telling("mention", &seed.carol, Some(&seed.carol_post)),
            telling("mention", &seed.dave, Some(&seed.dave_post)),
        ]),
        "and the mentions are their own keep"
    );
    let dropped = sorted(told(
        &flat(
            &app,
            &seed.alice,
            "?exclude_types[]=mention&exclude_types[]=follow",
        )
        .await,
    ));
    assert_eq!(
        dropped,
        sorted(vec![
            owed("favourite", &seed.bob),
            owed("favourite", &seed.dave),
            owed("pleroma:emoji_reaction", &seed.bob),
            owed("reblog", &seed.carol),
        ]),
        "exclude_types[] drops the two mentions and the follow"
    );
}

/// On the mixed page the `min_id`/`max_id`/`since_id` cursors walk the id
/// order (decision 4): `max_id` older, `since_id` newer, `min_id` read
/// forward and answered flipped, an exhausted walk empty, `limit` cutting
/// the head — all keyed on the ids the unfiltered page itself reported.
#[tokio::test]
async fn the_flat_page_walks_its_id_cursors() {
    let db = common::test_db().await;
    let pool = db.pool().clone();
    let app = common::test_app(pool.clone());
    let seed = mix(&app, &pool).await;

    let full = ids_of(&flat(&app, &seed.alice, "").await);
    assert_eq!(full.len(), 7, "seven tellings on the page");
    let page = |query: String| {
        let application = app.clone();
        let token = seed.alice.clone();
        async move { ids_of(&flat(&application, &token, &query).await) }
    };

    assert_eq!(
        page("?limit=3".to_owned()).await,
        full[0..3],
        "limit cuts the newest head of the page"
    );
    assert_eq!(
        page(format!("?max_id={}", full[3])).await,
        full[4..7],
        "max_id keeps strictly older rows"
    );
    assert_eq!(
        page(format!("?since_id={}", full[3])).await,
        full[0..3],
        "since_id keeps the newer rows, newest first"
    );
    assert_eq!(
        page(format!("?min_id={}&limit=2", full[3])).await,
        vec![full[1].clone(), full[2].clone()],
        "a min_id page reads forward and answers flipped"
    );
    assert!(
        page(format!("?max_id={}", full[6])).await.is_empty(),
        "older than the oldest row answers nothing"
    );
}
